    private void fixture(boolean revoke)throws Exception{String token=UUID.randomUUID().toString();ui(()->home.startActivity(new Intent().setComponent(new ComponentName("com.nthexperience.desktop.fixture","com.nthexperience.desktop.fixture.GrantActivity")).putExtra("revoke",revoke).putExtra("receipt",token)));long end=SystemClock.uptimeMillis()+12000;boolean done=false;while(SystemClock.uptimeMillis()<end){try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand("run-as com.nthexperience.desktop.fixture cat files/grant-receipt.txt");InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[1024];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);if(token.equals(out.toString("UTF-8"))){done=true;break;}}Thread.sleep(100);}check(done,"Fixture completed the requested grant operation");await(()->home.hasWindowFocus(),"Fixture returns input focus to launcher");if(revoke)awayAndBack();}
