    private byte[] image(Bitmap.CompressFormat format){Bitmap bitmap=Bitmap.createBitmap(80,40,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);Paint p=new Paint();p.setColor(Color.RED);canvas.drawRect(0,0,40,20,p);p.setColor(Color.GREEN);canvas.drawRect(40,0,80,20,p);p.setColor(Color.BLUE);canvas.drawRect(0,20,40,40,p);p.setColor(Color.YELLOW);canvas.drawRect(40,20,80,40,p);ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(format,100,out);bitmap.recycle();return out.toByteArray();}
    private Uri put(Uri folder,String name,String mime,byte[] data)throws Exception{Uri uri=DocumentsContract.createDocument(getTargetContext().getContentResolver(),folder,mime,name);check(uri!=null,"Fixture created");try(OutputStream out=getTargetContext().getContentResolver().openOutputStream(uri)){out.write(data);}return uri;}
    private String hash(Uri uri)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=getTargetContext().getContentResolver().openInputStream(uri)){byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1)digest.update(buffer,0,n);}return android.util.Base64.encodeToString(digest.digest(),android.util.Base64.NO_WRAP);}
    private int pixel(){int[] color={0};runOnMainSync(()->{Bitmap bitmap=Bitmap.createBitmap(gallery.canvas.getWidth(),gallery.canvas.getHeight(),Bitmap.Config.ARGB_8888);gallery.canvas.draw(new Canvas(bitmap));color[0]=bitmap.getPixel(bitmap.getWidth()/2-Math.min(bitmap.getWidth(),bitmap.getHeight())/8,bitmap.getHeight()/2-Math.min(bitmap.getWidth(),bitmap.getHeight())/8);bitmap.recycle();});return color[0];}
    private boolean red(int color){return Color.red(color)>180&&Color.blue(color)<80;}private boolean blue(int color){return Color.blue(color)>180&&Color.red(color)<80;}
    private View findText(String text){return find(home.getWindow().getDecorView(),v->text.contentEquals(v.getContentDescription()==null?"":v.getContentDescription())||v instanceof TextView&&text.contentEquals(((TextView)v).getText()));}
    private View find(View root,Predicate<View> test){if(root==null||!root.isShown())return null;if(test.test(root))return root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){View result=find(((ViewGroup)root).getChildAt(i),test);if(result!=null)return result;}return null;}
    private void tap(String text)throws Exception{tap(text,true);}private void tap(String text,boolean enabled)throws Exception{await(()->findText(text)!=null,"Control visible: "+text);View view=findText(text);if(!enabled){check(!view.isEnabled(),"Control is correctly disabled: "+text);return;}tapView(view);}
    private void tapView(View view)throws Exception{check(view!=null&&view.isEnabled(),"Touchable control");String description=String.valueOf(view.getContentDescription());Rect bounds=new Rect();boolean[] visible={false};for(int attempt=0;attempt<4&&!visible[0];attempt++){runOnMainSync(()->{View target=description.startsWith("Restore ")?findText(description):view;if(target!=null&&target.isAttachedToWindow()){visible[0]=target.getGlobalVisibleRect(bounds);if(!visible[0])target.requestRectangleOnScreen(new Rect(0,0,target.getWidth(),target.getHeight()),true);}});if(!visible[0])Thread.sleep(150);}check(visible[0],"Control has visible touch bounds: "+description);touch(bounds.exactCenterX(),bounds.exactCenterY());}
    private void touch(float x,float y)throws Exception{long now=SystemClock.uptimeMillis();for(int action:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_UP}){MotionEvent event=MotionEvent.obtain(now,SystemClock.uptimeMillis(),action,x,y,0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);check(getUiAutomation().injectInputEvent(event,true),"Touch accepted");event.recycle();Thread.sleep(70);}Thread.sleep(180);}
    private void systemTap(String text)throws Exception{await(()->node(getUiAutomation().getRootInActiveWindow(),text)!=null,"Dialog control: "+text);getUiAutomation().waitForIdle(200,3000);AccessibilityNodeInfo node=node(getUiAutomation().getRootInActiveWindow(),text);while(node!=null&&!node.isClickable())node=node.getParent();check(node!=null,"Dialog action clickable");Rect bounds=new Rect();node.getBoundsInScreen(bounds);touch(bounds.exactCenterX(),bounds.exactCenterY());}
    private AccessibilityNodeInfo node(AccessibilityNodeInfo root,String text){if(root==null)return null;if(text.contentEquals(root.getText()==null?"":root.getText())||text.contentEquals(root.getContentDescription()==null?"":root.getContentDescription()))return root;for(int i=0;i<root.getChildCount();i++){AccessibilityNodeInfo found=node(root.getChild(i),text);if(found!=null)return found;}return null;}
    private void ui(Runnable action){runOnMainSync(action);try{Thread.sleep(120);}catch(InterruptedException failure){throw new AssertionError(failure);}}
    private void await(BooleanSupplier condition,String text)throws Exception{long end=SystemClock.uptimeMillis()+20000;while(SystemClock.uptimeMillis()<end){boolean[] ready={false};runOnMainSync(()->ready[0]=condition.getAsBoolean());if(ready[0])return;Thread.sleep(100);}throw new AssertionError(text);}
    private void cleanup(){for(Uri folder:new Uri[]{nativeFolder,linkedFolder})if(folder!=null)try{DocumentOps.delete(getTargetContext(),Collections.singletonList(new DocumentOps.Ref(folder,null,DocumentOps.stat(getTargetContext(),folder,new DocumentOps.Cancel()))),new DocumentOps.Cancel());}catch(Exception ignored){}}
    private void shot(String name)throws Exception{Bitmap image=getUiAutomation().takeScreenshot();check(image!=null,"Screenshot available");try(FileOutputStream out=getTargetContext().openFileOutput(name+".png",0)){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
    private void progress(String text){Bundle out=new Bundle();out.putString("stream","CHECK: "+text+"\n");sendStatus(1,out);}
